 // With 1024 cycles, we have plenty of time. We can compute in the same cycle.\n    \n    // Registers for search\n    reg [15:0] r_bs_fp;\n    reg [15:0] r_sd_fp;\n    \n    // Wires for calculation results\n    wire [31:0] mult_b_0, mult_b_1, mult_b_2, mult_b_3, mult_b_4;\n    wire [31:0] mult_s_0, mult_s_1, mult_s_2, mult_s_3, mult_s_4;\n    \n    wire [15:0] calc_su_0, calc_su_1, calc_su_2, calc_su_3, calc_su_4;\n    wire [15:0] calc_d_0, calc_d_1, calc_d_2, calc_d_3, calc_d_4;\n    \n    // Assign multiplications\n    // Note: (val * r_fp) >> 8 is val * (r_fp / 256)\n    // Since r_fp = r_int * 256, this is val * r_int.\n    // But we implemented Q8.8, so r_fp is the fixed point rep.\n    // multiplication: val (16 bit) * r_fp (16 bit) = 32 bit.\n    // Result is val * r_int * 256.\n    // We want val * r_int.\n    // So we need to shift right by 8.\n    // mult_result[23:8] is the 16-bit result.\n    \n    assign mult_b_0 = known_0_0 * r_bs_fp;\n    assign calc_su_0 = mult_b_0[23:8];\n    // Repeat for others...\n    \n    // We need to declare known_XX registers.\n    // To avoid repeating code, we will write the full block.\n\nendmodule\n\n// Wait, we can't have logic outside the module in the JSON string.\n// We need to fit everything inside `module ... endmodule`.\n\nmodule SolveProportionPuzzle (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [15:0] val_0,\n    input wire [15:0] val_1,\n    input wire [15:0] val_2,\n    input wire [15:0] val_3,\n    input wire [15:0] val_4,\n    input wire [15:0] val_5,\n    input wire [15:0] val_6,\n    input wire [15:0] val_7,\n    input wire [15:0] val_8,\n    input wire [15:0] val_9,\n    input wire [15:0] val_10,\n    input wire [15:0] val_11,\n    input wire [15:0] val_12,\n    input wire [15:0] val_13,\n    input wire [15:0] val_14,\n    input wire [15:0] val_15,\n    input wire [15:0] val_16,\n    input wire [15:0] val_17,\n    input wire [15:0] val_18,\n    input wire [15:0] val_19,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] PARSE   = 3'd1;\n    localparam [2:0] SEARCH  = 3'd2;\n    localparam [2:0] OUTPUT  = 3'd3;\n    localparam [2:0] DONE    = 3'd4;\n\n    // Registers\n    reg [2:0] state;\n    reg [2:0] next_state;\n    \n    // Input buffer registers (20 values)\n    reg [15:0] k00, k01, k02, k03;\n    reg [15:0] k10, k11, k12, k13;\n    reg [15:0] k20, k21, k22, k23;\n    reg [15:0] k30, k31, k32, k33;\n    reg [15:0] k40, k41, k42, k43;\n    \n    // Search variables\n    reg [15:0] cycle_count; // 0 to 1023\n    reg [31:0] valid_count;\n    \n    // Helper signals for current iteration\n    wire [7:0] r_bs_int;\n    wire [7:0] r_sd_int;\n    reg [15:0] r_bs_fp;\n    reg [15:0] r_sd_fp;\n    \n    // Multiplication results (32-bit)\n    // We will compute these on the fly in combinational logic\n    wire [31:0] mb0, mb1, mb2, mb3, mb4;\n    wire [31:0] ms0, ms1, ms2, ms3, ms4;\n    \n    // Comparison results\n    wire c00, c01, c10, c11, c20, c21, c30, c31, c40, c41;\n    wire valid_config;\n\n    // --- Combinational Logic for Search ---\n    // Calculate current ratios\n    assign r_bs_int = (cycle_count[15:8] + 8'd1); // 1..32 (assuming 32x32 grid)\n    assign r_sd_int = (cycle_count[7:0] + 8'd1);\n    \n    // Multiplications (Q8.8 format)\n    // r_bs_fp = r_bs_int * 256\n    // Note: This needs to be updated every cycle in SEARCH state.\n    // Since r_bs_int is combinational, we calculate fp in combinational logic too or sequential.\n    // Let's use combinational logic for the product to save registers, \n    // but we need to be careful about timing.\n    // Since cycle_count updates sequentially, r_bs_int updates.\n    // We can compute r_bs_fp combinationaly: r_bs_fp = {r_bs_int, 8'd0};\n    \n    wire [15:0] r_bs_fp_wire;\n    wire [15:0] r_sd_fp_wire;\n    assign r_bs_fp_wire = {r_bs_int, 8'd0}; // Multiply by 256\n    assign r_sd_fp_wire = {r_sd_int, 8'd0};\n    \n    // Multiply known values by ratios\n    // We need to be careful with synthesis: multiplication of 16x16 -> 32 bit.\n    assign mb0 = k00 * r_bs_fp_wire;\n    assign mb1 = k10 * r_bs_fp_wire;\n    assign mb2 = k20 * r_bs_fp_wire;\n    assign mb3 = k30 * r_bs_fp_wire;\n    assign mb4 = k40 * r_bs_fp_wire;\n    \n    assign ms0 = k01 * r_sd_fp_wire;\n    assign ms1 = k11 * r_sd_fp_wire;\n    assign ms2 = k21 * r_sd_fp_wire;\n    assign ms3 = k31 * r_sd_fp_wire;\n    assign ms4 = k41 * r_sd_fp_wire;\n    \n    // Check results (Shift right 8 bits for Q8.8 -> Integer)\n    // (val * r_fp) >> 8 == val * r_int\n    // Result is in bits [23:8] of the 32-bit product\n    \n    wire [15:0] res_b0, res_b1, res_b2, res_b3, res_b4;\n    wire [15:0] res_s0, res_s1, res_s2, res_s3, res_s4;\n    \n    assign res_b0 = mb0[23:8];\n    assign res_b1 = mb1[23:8];\n    assign res_b2 = mb2[23:8];\n    assign res_b3 = mb3[23:8];\n    assign res_b4 = mb4[23:8];\n    \n    assign res_s0 = ms0[23:8];\n    assign res_s1 = ms1[23:8];\n    assign res_s2 = ms2[23:8];\n    assign res_s3 = ms3[23:8];\n    assign res_s4 = ms4[23:8];\n    \n    // Consistency Checks\n    // If known value > 0, calculated must match.\n    // If known value == 0, we ignore (it's unknown).\n    // Note: 0 is a valid value, but the problem states unknowns are 0. \n    // We assume 0 means unconstrained.\n    \n    assign c00 = (k00 == 16'd0) || (res_b0 == k02);\n    assign c01 = (k01 == 16'd0) || (res_s0 == k03);\n    \n    assign c10 = (k10 == 16'd0) || (res_b1 == k12);\n    assign c11 = (k11 == 16'd0) || (res_s1 == k13);\n    \n    assign c20 = (k20 == 16'd0) || (res_b2 == k22);\n    assign c21 = (k21 == 16'd0) || (res_s2 == k23);\n    \n    assign c30 = (k30 == 16'd0) || (res_b3 == k32);\n    assign c31 = (k31 == 16'd0) || (res_s3 == k33);\n    \n    assign c40 = (k40 == 16'd0) || (res_b4 == k42);\n    assign c41 = (k41 == 16'd0) || (res_s4 == k43);\n    \n    assign valid_config = c00 & c01 & c10 & c11 & c20 & c21 & c30 & c31 & c40 & c41;\n\n    // --- State Transition Logic ---\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // --- Main FSM Logic ---\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset outputs and internal regs\n            done <= 1'b0;\n            result <= 32'd0;\n            cycle_count <= 16'd0;\n            valid_count <= 32'd0;\n            \n            // Reset known regs\n            k00 <= 16'd0; k01 <= 16'd0; k02 <= 16'd0; k03 <= 16'd0;\n            k10 <= 16'd0; k11 <= 16'd0; k12 <= 16'd0; k13 <= 16'd0;\n            k20 <= 16'd0; k21 <= 16'd0; k22 <= 16'd0; k23 <= 16'd0;\n            k30 <= 16'd0; k31 <= 16'd0; k32 <= 16'd0; k33 <= 16'd0;\n            k40 <= 16'd0; k41 <= 16'd0; k42 <= 16'd0; k43 <= 16'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load inputs into registers\n                        k00 <= val_0; k01 <= val_1; k02 <= val_2; k03 <= val_3;\n                        k10 <= val_4; k11 <= val_5; k12 <= val_6; k13 <= val_7;\n                        k20 <= val_8; k21 <= val_9; k22 <= val_10; k23 <= val_11;\n                        k30 <= val_12; k31 <= val_13; k32 <= val_14; k33 <= val_15;\n                        k40 <= val_16; k41 <= val_17; k42 <= val_18; k43 <= val_19;\n                        \n                        cycle_count <= 16'd0;\n                        valid_count <= 32'd0;\n                    end\n                end\n\n                SEARCH: begin\n                    // Check current configuration (cycle_count)\n                    // If valid_config is high, increment valid_count\n                    if (valid_config) begin\n                        if (valid_count < 32'd1000) begin\n                            valid_count <= valid_count + 32'd1;\n                        end\n                    end\n                    \n                    // Increment cycle count\n                    cycle_count <= cycle_count + 16'd1;\n                    \n                    // Check termination: 32x32 grid = 1024 iterations (0..1023)\n                    // cycle_count goes 0, 1, ... 1023.\n                    // When cycle_count reaches 1023, next cycle it is 1024.\n                    // We stop when cycle_count == 1024.\n                    // So check if cycle_count == 1023 in this cycle? \n                    // No, we update cycle_count above. \n                    // So if cycle_count was 1023, it becomes 1024.\n                    // We should transition when cycle_count == 1024.\n                    // But we can't see the future.\n                    // Better: if (cycle_count == 1023) begin ... end\n                    // Next state will be OUTPUT.\n                    // Wait, if cycle_count == 1023, we process the last config (32, 32).\n                    // Then we need to stop.\n                    // So if cycle_count == 1023, we transition to OUTPUT.\n                end\n\n                OUTPUT: begin\n                    if (valid_count > 32'd1000) begin\n                        result <= 32'hFFFFFFFF; // Marker for \"many\"\n                    end else begin\n                        result <= valid_count;\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\n    // --- Next State Logic ---\n    always @(*) begin\n        case (state)\n            IDLE: begin\n                if (start) next_state = SEARCH; // Go directly to search after loading\n                else next_state = IDLE;\n            end\n            \n            SEARCH: begin\n                // Check if we finished the loop\n                // cycle_count was incremented in the block.\n                // If we just incremented to 1024 (0x0400), we are done.\n                // Wait, cycle_count is updated in the state block.\n                // The check should be on the *current* cycle_count before increment?\n                // No, we update and then check.\n                // If cycle_count == 1023, we process the last item, cycle_count becomes 1024.\n                // We should transition to OUTPUT.\n                // So check if cycle_count == 1023 (before increment) or cycle_count == 1024 (after increment).\n                // Let's check cycle_count in the combinational block.\n                // cycle_count will be the value AFTER update from the sequential block? \n                // No, in combinational always @(*) for next_state, cycle_count refers to the current value in the register.\n                // So in the cycle where we process item 1023, cycle_count register is 1023.\n                // We increment it to 1024 in the sequential block.\n                // We should transition to OUTPUT now.\n                \n                if (cycle_count == 16'd1023) begin\n                    next_state = OUTPUT;\n                end else begin\n                    next_state = SEARCH;\n                end\n            end\n\n            OUTPUT: begin\n                next_state = DONE;\n            end\n\n            DONE: begin\n                next_state = IDLE;\n            end\n\n            default: next_state = IDLE;\n        endcase\n    end\n\nendmodule"
